package sample;

import com.nutanix.hw.java.client.ApiClient;
import com.nutanix.hw.java.client.api.BmcApi;
import com.nutanix.dp1.hw.clustermgmt.v4.request.Bmc.GetBmcInfoRequest;
import com.nutanix.dp1.hw.clustermgmt.v4.config.GetBmcInfoResponse;
import org.springframework.web.client.RestClientException;

public class JavaSdkSample {
    public static void main(String[] args) {
        // Configure the client
        ApiClient apiClient = new ApiClient();
        // IPv4/IPv6 address or FQDN of the cluster
        apiClient.setHost("localhost");
        // Port used for the connection. PC products typically use port 9440, while NC products typically use port 443. See the product-specific documentation for accurate configuration.
        apiClient.setPort(9440);
        // Interval in ms to use during retry attempts
        apiClient.setRetryInterval(5000);
        // Max retry attempts while reconnecting on a loss of connection
        apiClient.setMaxRetryAttempts(5);
        // UserName to connect to the cluster
        String username = "username";
        // Password to connect to the cluster
        String password = "password";
        apiClient.setUsername(username);
        apiClient.setPassword(password);

        // Please add authorization information here if needed.
        BmcApi bmcApi = new BmcApi(apiClient);


        String clusterExtId = "B1d5e83A-E8Bb-ADBD-0C1d-DD2ba6bAfeDF";

        String extId = "1FD878B9-a7a8-fdDc-cc0B-CCEDFA3A9aa2";

        try {
            // Pass in parameters using the request builder object associated with the operation.
            GetBmcInfoResponse getBmcInfoResponse = bmcApi.getBmcInfo(GetBmcInfoRequest.builder()
                .clusterExtId(clusterExtId)
                .extId(extId)
                .build());

            System.out.println(getBmcInfoResponse.toString());

        } catch (RestClientException ex) {
            System.out.println(ex.getMessage());
        }
    }
}

