        // TrafficMirror object initializations here...

        String extId = "3fdbFabe-cbFc-CAfe-7ed6-aBaE7Efb758b";

        // perform GET call
        GetTrafficMirrorApiResponse getResponse = null;
        try {
            getResponse = trafficMirrorsApi.getTrafficMirrorById(extId);
